with matched_keys as (select customer_id, status from subscriptions intersect all select customer_id, status from subscriptions where plan not in ('premium', 'standard')), kept_rows as (select s.* from subscriptions s join matched_keys k on s.customer_id = k.customer_id and s.status = k.status) select case when monthly_fee >= 250 then 'PREMIUM' else 'STANDARD' end as monthly_fee_tier, round(sum(monthly_fee) / nullif(count(case when status = 'ACTIVE' then 1 end), 0), 2) as monthly_fee_per_active, round(sum(monthly_fee) / nullif(count(case when status = 'EXPIRED' then 1 end), 0), 2) as monthly_fee_per_expired, sum(monthly_fee) as total_monthly_fee, grouping_id() as gid from kept_rows group by cube (case when monthly_fee >= 250 then 'PREMIUM' else 'STANDARD' end);
